"""Topic path subscription matcher."""

def _is_exact_segment_match(subscribed_pattern: str, event_topic: str) -> bool:
    """
    Checks if event_topic exactly matches the subscribed_pattern,
    or if event_topic starts with subscribed_pattern followed by '::'.
    This enforces segment boundary checks as per H06.
    """
    if event_topic == subscribed_pattern:
        return True
    if event_topic.startswith(subscribed_pattern + "::"):
        return True
    return False

def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    """
    Determines if an event_topic matches a subscribed_pattern,
    respecting hierarchical segment boundaries.

    Handles basic direct matches and hierarchical prefix matches.
    Wildcard matching for '*' and '**' is not implemented here,
    as per the scope of the EVT-918 ticket addressing non-wildcard
    subscription patterns.
    """
    return _is_exact_segment_match(subscribed_pattern, event_topic)

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
